function App() {
  // Mock of useActionState: action returns { error } or { ok: true }.
  const fakeAction = (prev, formData) => new Promise(res => {
    const title = formData.get('title');
    setTimeout(() => res(title ? { ok: true, title } : { error: 'Title required' }), 700);
  });
  const [state, setState] = useState({});
  const [pending, setPending] = useState(false);
  async function onSubmit(e) {
    e.preventDefault();
    setPending(true);
    const result = await fakeAction(state, new FormData(e.target));
    setState(result);
    setPending(false);
  }
  return (
    <form onSubmit={onSubmit} style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input name="title" placeholder="New todo" />
      <button disabled={pending}>{pending ? 'Saving…' : 'Add'}</button>
      {state.error && <p style={{ color: 'crimson' }}>{state.error}</p>}
      {state.ok && <p style={{ color: 'green' }}>Added: {state.title}</p>}
    </form>
  );
}

