// app/actions.ts
'use server';
import { z } from 'zod';
import { revalidateTag } from 'next/cache';
import { getSession } from '@/lib/auth';
import { db } from '@/lib/db';

const Schema = z.object({ title: z.string().min(1, 'Title required') });

export async function createTodo(prevState, formData) {
  const user = await getSession();
  if (!user) return { error: 'Unauthorized' };

  const parsed = Schema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) {
    return { error: parsed.error.issues[0].message };
  }

  await db.todo.create({ data: { title: parsed.data.title, userId: user.id } });
  revalidateTag('todos');
  return { ok: true };
}

// app/TodoForm.tsx
'use client';
import { useActionState } from 'react';
import { useFormStatus } from 'react-dom';
import { createTodo } from './actions';

function SubmitButton() {
  const { pending } = useFormStatus();
  return <button disabled={pending}>{pending ? 'Saving…' : 'Add'}</button>;
}

export function TodoForm() {
  const [state, formAction] = useActionState(createTodo, {});
  return (
    <form action={formAction}>
      <input name="title" />
      <SubmitButton />
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}
